module tensor

type tensor = {data : []f32, shape : []i64, strides : []i64, ndim : i64}

let product [n] (arr : [n]i64) : i64 =
  reduce (*) 1 arr

let compute_strides (shape : []i64) : []i64 =
  let ndim = length shape
  in tabulate ndim (\i ->
       product (slice shape (i + 1) (ndim - i - 1)))

let getIndex (indices : []i64) (strides : []i64) : i64 =
  reduce (+) 0 (zipWith (*) indices strides)

let unflat (lin : i64) (strides : []i64) (shape : []i64) : []i64 =
  let ndim = length shape
  in loop (idx, rem) = (replicate ndim 0, lin) for i < ndim do
       let q = rem / strides[i]
       let idx' = idx with [i] = q
       let rem' = rem % strides[i]
       in (idx', rem')

let init [n] (shape : []i64) : tensor =
  let ndim = length shape
  let data : [n]f32 = replicate n 0.0f32
  let strides = compute_strides shape
  in {data = data, shape = copy shape, strides = strides, ndim = ndim}

let deinit [n] (t : tensor) : [n]f32 =
  t.data

let copy [n] (t : tensor) : tensor =
  {data = copy t.data, shape = copy t.shape, strides = copy t.strides, ndim = t.ndim}

let fill [n] (t : tensor) (value : f32) : tensor =
  {data = replicate n value, shape = t.shape, strides = t.strides, ndim = t.ndim}

let get (t : tensor) (indices : []i64) : f32 =
  t.data[getIndex indices t.strides]

let set [n] (t : tensor) (indices : []i64) (value : f32) : tensor =
  let idx = getIndex indices t.strides
  in {data = t.data with [idx] = value, shape = t.shape, strides = t.strides, ndim = t.ndim}

let add [n] (t1 : tensor) (t2 : tensor) : tensor =
  if t1.shape != t2.shape then error "ShapeMismatch"
  else {data = map2 (+) t1.data t2.data, shape = t1.shape, strides = t1.strides, ndim = t1.ndim}

let sub [n] (t1 : tensor) (t2 : tensor) : tensor =
  if t1.shape != t2.shape then error "ShapeMismatch"
  else {data = map2 (-) t1.data t2.data, shape = t1.shape, strides = t1.strides, ndim = t1.ndim}

let mul [n] (t1 : tensor) (t2 : tensor) : tensor =
  if t1.shape != t2.shape then error "ShapeMismatch"
  else {data = map2 (*) t1.data t2.data, shape = t1.shape, strides = t1.strides, ndim = t1.ndim}

let div [n] (t1 : tensor) (t2 : tensor) : tensor =
  if t1.shape != t2.shape then error "ShapeMismatch"
  else {data = map2 (/) t1.data t2.data, shape = t1.shape, strides = t1.strides, ndim = t1.ndim}

let addScalar [n] (t : tensor) (scalar : f32) : tensor =
  {data = map (+ scalar) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let subScalar [n] (t : tensor) (scalar : f32) : tensor =
  {data = map (\x -> x - scalar) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let mulScalar [n] (t : tensor) (scalar : f32) : tensor =
  {data = map (* scalar) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let divScalar [n] (t : tensor) (scalar : f32) : tensor =
  {data = map (/ scalar) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let exp [n] (t : tensor) : tensor =
  {data = map f32.exp t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let log [n] (t : tensor) : tensor =
  {data = map f32.log t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let sin [n] (t : tensor) : tensor =
  {data = map f32.sin t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let cos [n] (t : tensor) : tensor =
  {data = map f32.cos t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let tan [n] (t : tensor) : tensor =
  {data = map f32.tan t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let sqrt [n] (t : tensor) : tensor =
  {data = map f32.sqrt t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let pow [n] (t : tensor) (expn : f32) : tensor =
  {data = map (\x -> f32.pow x expn) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let abs [n] (t : tensor) : tensor =
  {data = map f32.abs t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let max_along_axis [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         in reduce f32.max (-f32.inf) (tabulate old_size (\j -> data[base + j * s_axis]))
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let min_along_axis [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         in reduce f32.min f32.inf (tabulate old_size (\j -> data[base + j * s_axis]))
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let sum_along_axis [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         in reduce (+) 0.0f32 (tabulate old_size (\j -> data[base + j * s_axis]))
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let mean [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let s = sum_along_axis t axis
  let n_f = f32.i64 old_size
  in divScalar s n_f

let variance [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size <= 1 then error "InvalidAxis or InvalidForVariance"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let ddof = 1.0f32
       let n_f = f32.i64 old_size
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         let sumv = reduce (+) 0.0f32 (tabulate old_size (\j -> data[base + j * s_axis]))
         let meanv = sumv / n_f
         let sum_sq = reduce (+) 0.0f32 (tabulate old_size (\j ->
           let x = data[base + j * s_axis]
           let d = x - meanv
           in d * d
         ))
         in sum_sq / (n_f - ddof)
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let stddev [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  sqrt (variance t axis)

let argmax [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         let (maxv, maxj) = reduce (\(v1, j1) (v2, j2) -> if v1 > v2 then (v1, j1) else (v2, j2)) (-f32.inf, 0i64)
           (tabulate old_size (\j ->
             let v = data[base + j * s_axis]
             in (v, j)
           ))
         in f32.i64 maxj
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let argmin [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let new_shape = copy shape with [axis] = 1
       let new_strides = compute_strides new_shape
       let s_axis = strides[axis]
       let new_data : [new_size]f32 = map (\p ->
         let red_idx = unflat p new_strides new_shape
         let base = getIndex red_idx strides
         let (minv, minj) = reduce (\(v1, j1) (v2, j2) -> if v1 < v2 then (v1, j1) else (v2, j2)) (f32.inf, 0i64)
           (tabulate old_size (\j ->
             let v = data[base + j * s_axis]
             in (v, j)
           ))
         in f32.i64 minj
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let broadcast [target_size] (t : tensor) (target_shape : []i64) : tensor =
  let ndim = t.ndim
  in if length target_shape != ndim then error "ShapeMismatch"
  else if not all (\i ->
    let s1 = t.shape[i]
    let s2 = target_shape[i]
    in s1 == s2 || s1 == 1 || s2 == 1
  ) (iota ndim) then error "BroadcastIncompatible"
  else let target_strides = compute_strides target_shape
       let new_data : [target_size]f32 = map (\lin ->
         let target_idx = unflat lin target_strides target_shape
         let src_idx = map2 (%) target_idx t.shape
         in get t src_idx
       ) (iota target_size)
       let new_strides = target_strides
       in {data = new_data, shape = target_shape, strides = new_strides, ndim = ndim}

let reshape [n] (t : tensor) (new_shape : []i64) : tensor =
  let new_size = product new_shape
  in if new_size != n then error "InvalidReshape"
  else let new_ndim = length new_shape
       let new_strides = compute_strides new_shape
       in {data = t.data, shape = new_shape, strides = new_strides, ndim = new_ndim}

let transpose [n] (t : tensor) (axes : []i64) : tensor =
  let ndim = t.ndim
  in if length axes != ndim then error "InvalidAxes"
  else let new_shape = map (\a -> t.shape[a]) axes
       let new_strides = map (\i -> t.strides[axes[i]]) (iota ndim)
       in {data = t.data, shape = new_shape, strides = new_strides, ndim = ndim}

let slice [new_size] (t : tensor) (ranges : [][]i64) : tensor =
  let ndim = t.ndim
  in if length ranges != ndim then error "InvalidRanges"
  else let starts : [ndim]i64 = map (\r -> r[0]) ranges
       let ends : [ndim]i64 = map (\r -> r[1]) ranges
       let new_shape : [ndim]i64 = map2 (-) ends starts
       let new_strides = compute_strides (new_shape :> []i64)
       let new_data : [new_size]f32 = map (\lin ->
         let new_idx = unflat lin new_strides (new_shape :> []i64)
         let old_idx = map2 (+) new_idx starts
         in get t old_idx
       ) (iota new_size)
       in {data = new_data, shape = new_shape :> []i64, strides = new_strides, ndim = ndim}

let concatenate [new_size] [num] (tensors : [num]tensor) (axis : i64) : tensor =
  if num == 0 then error "EmptyConcat"
  else let ref = tensors[0]
       let ndim = ref.ndim
       in if axis < 0 || axis >= ndim then error "InvalidAxis"
       else let sizes : [num]i64 = map (\ten -> ten.shape[axis]) tensors
            let cum_off : [num+1]i64 = scanl (+) 0 sizes
            let new_shape = copy ref.shape with [axis] = cum_off[num]
            let new_strides = compute_strides new_shape
            let new_data : [new_size]f32 = map (\lin ->
              let new_idx = unflat lin new_strides new_shape
              let ax = new_idx[axis]
              let k = loop kk = 0i64 for i < num do
                if ax < cum_off[i + 1] then kk else i + 1
              let off = cum_off[k]
              let local_ax = ax - off
              let local_idx = new_idx with [axis] = local_ax
              in get tensors[k] local_idx
            ) (iota new_size)
            in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let stack [new_size] [num] (tensors : [num]tensor) (axis : i64) : tensor =
  if num == 0 then error "EmptyStack"
  else let ref = tensors[0]
       let ndim = ref.ndim
       in if axis < 0 || axis > ndim then error "InvalidAxis"
       else let new_shape = if axis == ndim then
              ref.shape ++ [num]
            else
              loop sh = replicate (ndim + 1) 0i64 for i < ndim + 1 do
                if i < axis then sh[i] = ref.shape[i]
                elif i == axis then sh[i] = num
                else sh[i] = ref.shape[i - 1]
                sh
            let new_ndim = ndim + 1
            let new_strides = compute_strides new_shape
            let new_data : [new_size]f32 = map (\lin ->
              let new_idx = unflat lin new_strides new_shape
              let ten_idx = new_idx[axis]
              let local_ndim = ndim
              let local_idx : [local_ndim]i64 = loop res = replicate local_ndim 0i64 for ii < local_ndim do
                let jj = if ii < axis then ii else ii + 1
                in res with [ii] = new_idx[jj]
              in get tensors[ten_idx] (local_idx :> []i64)
            ) (iota new_size)
            in {data = new_data, shape = new_shape, strides = new_strides, ndim = new_ndim}

let tile [new_size] (t : tensor) (reps : []i64) : tensor =
  let ndim = t.ndim
  in if length reps != ndim then error "InvalidReps"
  else let new_shape = map2 (*) t.shape reps
       let target_strides = compute_strides new_shape
       let new_data : [new_size]f32 = map (\lin ->
         let target_idx = unflat lin target_strides new_shape
         let src_idx = map2 (/) target_idx reps
         in get t src_idx
       ) (iota new_size)
       let new_strides = target_strides
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let pad [new_size] (t : tensor) (pads : [][]i64) : tensor =
  let ndim = t.ndim
  in if length pads != ndim then error "InvalidPads"
  else let new_shape = map2 (\s p -> s + p[0] + p[1]) t.shape pads
       let new_strides = compute_strides new_shape
       let start_pads : [ndim]i64 = map (\p -> p[0]) pads
       let new_data : [new_size]f32 = map (\lin ->
         let idx = unflat lin new_strides new_shape
         let is_pad = any (\ii ->
           let pos = idx[ii]
           let p = pads[ii]
           in pos < p[0] || pos >= p[0] + t.shape[ii]
         ) (iota ndim)
         in if is_pad then 0.0f32 else
            let src_idx = map2 (-) idx start_pads
            in get t src_idx
       ) (iota new_size)
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = ndim}

let clip [n] (t : tensor) (min_val : f32) (max_val : f32) : tensor =
  {data = map (\x -> f32.max min_val (f32.min max_val x)) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let normalize [n] [new_size] [old_size] (t : tensor) (axis : i64) (epsilon : f32) : tensor =
  if old_size == 0 then error "EmptyAxis"
  else let m = mean t axis
       let v = variance t axis
       let std = addScalar v epsilon |> sqrt
       let b_shape = t.shape with [axis] = 1
       let b_m = broadcast m b_shape
       let diff = sub t b_m
       let b_std = broadcast std b_shape
       in div diff b_std

let oneHot [n] [c] (t : tensor) (num_classes : i64) : tensor =
  if t.ndim != 1 then error "InvalidForOneHot"
  else let new_shape = [n, c]
       let total = n * c
       let new_data : [total]f32 = loop d = replicate total 0.0f32 for i < n do
         let val = t.data[i]
         let class_idx = i64.u32 (f32.round val)
         in if 0 <= class_idx && class_idx < c then
            let flat = i * c + class_idx
            in d with [flat] = 1.0f32
            else d
       let new_strides = compute_strides new_shape
       in {data = new_data, shape = new_shape, strides = new_strides, ndim = 2}

let cumsum [n] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let num_blocks = n / old_size
       let new_data = copy data
       let s_axis = strides[axis]
       let new_shape = shape
       let new_strides = strides
       let new_data' : [n]f32 = loop d = new_data for p < num_blocks do
         let new_sh = shape with [axis] = 1
         let new_st = compute_strides new_sh
         let red_idx = unflat (p * 1) new_st new_sh
         let base = getIndex red_idx strides
         let values : [old_size]f32 = tabulate old_size (\j -> data[base + j * s_axis])
         let prefix : [old_size]f32 = scanl (+) 0.0f32 values
         loop d' = d for j < old_size do
           d' with [base + j * s_axis] = prefix[j]
       in {data = new_data', shape = new_shape, strides = new_strides, ndim = ndim}

let cumprod [n] [old_size] (t : tensor) (axis : i64) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim || old_size == 0 then error "InvalidAxis or EmptyAxis"
  else let num_blocks = n / old_size
       let new_data = copy data
       let s_axis = strides[axis]
       let new_shape = shape
       let new_strides = strides
       let new_data' : [n]f32 = loop d = new_data for p < num_blocks do
         let new_sh = shape with [axis] = 1
         let new_st = compute_strides new_sh
         let red_idx = unflat (p * 1) new_st new_sh
         let base = getIndex red_idx strides
         let values : [old_size]f32 = tabulate old_size (\j -> data[base + j * s_axis])
         let prefix : [old_size]f32 = scanl (*) 1.0f32 values
         loop d' = d for j < old_size do
           d' with [base + j * s_axis] = prefix[j]
       in {data = new_data', shape = new_shape, strides = new_strides, ndim = ndim}

let sort_along_axis [n] [old_size] (t : tensor) (axis : i64) (descending : bool) : tensor =
  let {data, shape, strides, ndim} = t
  in if axis < 0 || axis >= ndim then error "InvalidAxis"
  else if old_size == 0 then t
  else let num_blocks = n / old_size
       let new_data = copy data
       let s_axis = strides[axis]
       let new_shape = shape
       let new_strides = strides
       let new_data' : [n]f32 = loop d = new_data for p < num_blocks do
         let new_sh = shape with [axis] = 1
         let new_st = compute_strides new_sh
         let red_idx = unflat (p * 1) new_st new_sh
         let base = getIndex red_idx strides
         let values : [old_size]f32 = tabulate old_size (\j -> data[base + j * s_axis])
         let sorted = if descending then
           map (\x -> -x) (sort (map (\x -> -x) values))
         else
           sort values
         loop d' = d for j < old_size do
           d' with [base + j * s_axis] = sorted[j]
       in {data = new_data', shape = new_shape, strides = new_strides, ndim = ndim}

let unique [n] (t : tensor) : tensor =
  if t.ndim != 1 then error "Unique for 1D only"
  else let sorted = sort t.data
       let (_, ud, count) = loop (i, ud, c) = (0, copy sorted, 0i64) for _ < n do
         if c == 0 || f32.abs (ud[c - 1] - sorted[i]) > 1e-6f32 then
           let ud' = ud with [c] = sorted[i]
           in (i + 1, ud', c + 1)
         else
           (i + 1, ud, c)
       let count_i64 = i64.u32 count
       let unique_data : [count_i64]f32 = copy (slice ud 0 count_i64)
       let u_shape = [count_i64]
       let u_strides = compute_strides u_shape
       in {data = unique_data, shape = u_shape, strides = u_strides, ndim = 1}

let isClose (t1 : tensor) (t2 : tensor) (rtol : f32) (atol : f32) : bool =
  if t1.shape != t2.shape then false
  else all (\(a, b) -> f32.abs (a - b) <= (atol + rtol * f32.abs b)) (zip t1.data t2.data)

let randomUniform [n] (t : tensor) (min_ : f32) (max_ : f32) (seed : u32) : tensor =
  -- Assuming random functions available
  let prng = random.init_prng seed
  let range = max_ - min_
  let new_data : [n]f32 = loop ds = replicate n 0.0f32 for _ < n do
    let u = random_f32 prng
    let val = u * range + min_
    ds with [length ds - 1] = val  -- simplistic, replace with proper
  in {data = new_data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let randomNormal [n] (t : tensor) (mean : f32) (stddev : f32) (seed : u32) : tensor =
  -- Assuming random functions available, Box-Muller
  let prng = random.init_prng seed
  let new_data = loop ds = replicate n 0.0f32 for ii < (n / 2 * 2) do
    let u1 = random_f32 prng
    let u2 = random_f32 prng
    let r = f32.sqrt (-2.0f32 * f32.log u1)
    let theta = 2.0f32 * f32.pi * u2
    let z0 = r * f32.cos theta
    let z1 = r * f32.sin theta
    let ds' = ds with [ii] = mean + stddev * z0
    let ds'' = if ii + 1 < n then ds' with [ii + 1] = mean + stddev * z1 else ds'
    ds''
  in {data = new_data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let arange (start : f32) (end_ : f32) (step : f32) : tensor =
  if step == 0.0f32 then error "ZeroStep"
  else let diff = end_ - start
       let num_f = if step > 0.0f32 then f32.floor (diff / step) else f32.ceil (diff / step)
       let num = i64.max 0 (f32.to_i64 num_f)
       let data : [num]f32 = map (\i -> start + step * f32.i64 i) (iota num)
       let sh = [num]
       let st = compute_strides sh
       in {data = data, shape = sh, strides = st, ndim = 1}

let linspace (start : f32) (end_ : f32) (num : i64) : tensor =
  if num == 0 then init [0]
  else if num == 1 then full [1] start
  else let step = (end_ - start) / f32.i64 (num - 1)
       let data : [num]f32 = map (\i -> start + step * f32.i64 i) (iota (num - 1)) ++ [end_]
       let sh = [num]
       let st = compute_strides sh
       in {data = data, shape = sh, strides = st, ndim = 1}

let eye (n : i64) : tensor =
  if n == 0 then init [0, 0]
  else let sh = [n, n]
       let t = init sh
       let data' = loop d = t.data for i < n do
         d with [i * n + i] = 1.0f32
       let st = compute_strides sh
       in {data = data', shape = sh, strides = st, ndim = 2}

let zeros [n] (shape : []i64) : tensor =
  init shape

let ones [n] (shape : []i64) : tensor =
  fill (init shape) 1.0f32

let full [n] (shape : []i64) (value : f32) : tensor =
  fill (init shape) value

let matmul [m] [n] [k] (a : tensor) (b : tensor) : tensor =
  if a.ndim != 2 || b.ndim != 2 || a.shape[1] != b.shape[0] then error "InvalidMatmul"
  else let a_data = a.data
       let b_data = b.data
       let c_data : [m*n]f32 = map (\ij ->
         let i = ij / n
         let j = ij % n
         in reduce (+) 0.0f32 (map (\kk -> a_data[i * k + kk] * b_data[kk * n + j]) (iota k))
       ) (iota (m * n))
       let new_shape = [m, n]
       let new_strides = compute_strides new_shape
       in {data = c_data, shape = new_shape, strides = new_strides, ndim = 2}

let conv2d [batch] [oh] [ow] [oc] [input_n] [kernel_n] (input : tensor) (kernel : tensor) (stride : [2]i64) (padding : [2]i64) : tensor =
  if input.ndim != 4 || kernel.ndim != 4 || input.shape[3] != kernel.shape[2] then error "InvalidConv2d"
  else let ih = input.shape[1]
       let iw = input.shape[2]
       let ic = input.shape[3]
       let kh = kernel.shape[0]
       let kw = kernel.shape[1]
       let oh_ = ((ih + 2 * padding[0] - kh) / stride[0]) + 1
       let ow_ = ((iw + 2 * padding[1] - kw) / stride[1]) + 1
       let pads_ : [4][2]i64 = [[[padding[0], padding[0]], [padding[1], padding[1]], [0, 0], [0, 0]]]
       let padded = pad input pads_
       let kernel_data = kernel.data
       let padded_data = padded.data
       let output_data : [batch*oh*ow*oc]f32 = map (\idx ->
         let b = idx / (oh * ow * oc)
         let oy = (idx / (ow * oc)) % oh
         let ox = (idx / oc) % ow
         let out_c = idx % oc
         in reduce (+) 0.0f32 (tabulate kh (\ky ->
           reduce (+) 0.0f32 (tabulate kw (\kx ->
             reduce (+) 0.0f32 (tabulate ic (\inc ->
               let y = oy * stride[0] + ky
               let x = ox * stride[1] + kx
               let input_idx = ((b * padded.shape[1] + y) * padded.shape[2] + x) * ic + inc
               let kernel_idx = ((ky * kw + kx) * ic + inc) * oc + out_c
               in padded_data[input_idx] * kernel_data[kernel_idx]
             ))
           ))
         ))
       ) (iota (batch * oh * ow * oc))
       let new_shape = [batch, oh, ow, oc]
       let new_strides = compute_strides new_shape
       in {data = output_data, shape = new_shape, strides = new_strides, ndim = 4}

let maxPool2d [batch] [oh] [ow] [channels] [input_n] (t : tensor) (kernel : [2]i64) (stride : [2]i64) (padding : [2]i64) : tensor =
  if t.ndim != 4 then error "InvalidPool2d"
  else let ih = t.shape[1]
       let iw = t.shape[2]
       let kh = kernel[0]
       let kw = kernel[1]
       let oh_ = ((ih + 2 * padding[0] - kh) / stride[0]) + 1
       let ow_ = ((iw + 2 * padding[1] - kw) / stride[1]) + 1
       let pads_ : [4][2]i64 = [[[padding[0], padding[0]], [padding[1], padding[1]], [0, 0], [0, 0]]]
       let padded = pad t pads_
       let data = padded.data
       let output_data : [batch*oh*ow*channels]f32 = map (\idx ->
         let b = idx / (oh * ow * channels)
         let oy = (idx / (ow * channels)) % oh
         let ox = (idx / channels) % ow
         let c = idx % channels
         in reduce f32.max (-f32.inf) (tabulate kh (\ky ->
           reduce f32.max (-f32.inf) (tabulate kw (\kx ->
             let y = oy * stride[0] + ky
             let x = ox * stride[1] + kx
             let pos = ((b * padded.shape[1] + y) * padded.shape[2] + x) * channels + c
             in data[pos]
           ))
         ))
       ) (iota (batch * oh * ow * channels))
       let new_shape = [batch, oh, ow, channels]
       let new_strides = compute_strides new_shape
       in {data = output_data, shape = new_shape, strides = new_strides, ndim = 4}

let avgPool2d [batch] [oh] [ow] [channels] [input_n] (t : tensor) (kernel : [2]i64) (stride : [2]i64) (padding : [2]i64) : tensor =
  if t.ndim != 4 then error "InvalidPool2d"
  else let ih = t.shape[1]
       let iw = t.shape[2]
       let kh = kernel[0]
       let kw = kernel[1]
       let oh_ = ((ih + 2 * padding[0] - kh) / stride[0]) + 1
       let ow_ = ((iw + 2 * padding[1] - kw) / stride[1]) + 1
       let pads_ : [4][2]i64 = [[[padding[0], padding[0]], [padding[1], padding[1]], [0, 0], [0, 0]]]
       let padded = pad t pads_
       let data = padded.data
       let area = f32.i64 (kh * kw)
       let output_data : [batch*oh*ow*channels]f32 = map (\idx ->
         let b = idx / (oh * ow * channels)
         let oy = (idx / (ow * channels)) % oh
         let ox = (idx / channels) % ow
         let c = idx % channels
         in reduce (+) 0.0f32 (tabulate kh (\ky ->
           reduce (+) 0.0f32 (tabulate kw (\kx ->
             let y = oy * stride[0] + ky
             let x = ox * stride[1] + kx
             let pos = ((b * padded.shape[1] + y) * padded.shape[2] + x) * channels + c
             in data[pos]
           ))
         )) / area
       ) (iota (batch * oh * ow * channels))
       let new_shape = [batch, oh, ow, channels]
       let new_strides = compute_strides new_shape
       in {data = output_data, shape = new_shape, strides = new_strides, ndim = 4}

let relu [n] (t : tensor) : tensor =
  {data = map (\x -> f32.max 0.0f32 x) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let leakyRelu [n] (t : tensor) (alpha : f32) : tensor =
  {data = map (\x -> if x > 0.0f32 then x else alpha * x) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let sigmoid [n] (t : tensor) : tensor =
  {data = map (\x -> 1.0f32 / (1.0f32 + f32.exp (-x))) t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let tanh [n] (t : tensor) : tensor =
  {data = map f32.tanh t.data, shape = t.shape, strides = t.strides, ndim = t.ndim}

let softmax [n] [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  if axis < 0 || axis >= t.ndim then error "InvalidAxis"
  else let max_t = max_along_axis t axis
       let b_shape = t.shape with [axis] = 1
       let b_max = broadcast max_t b_shape
       let shifted = sub t b_max
       let ex = exp shifted
       let sum_ex = sum_along_axis ex axis
       let b_sum = broadcast sum_ex b_shape
       in div ex b_sum

let logSoftmax [n] [new_size] [old_size] (t : tensor) (axis : i64) : tensor =
  log (softmax t axis)

let einsum [n] (t1 : tensor) (t2 : tensor) (equation : []u8) : tensor =
  if t1.ndim == 2 && t2.ndim == 2 && t1.shape[1] == t2.shape[0] then
    matmul t1 t2
  else error "NotImplemented"

let fusedAddMul [n] (t : tensor) (add_t : tensor) (mul_t : tensor) : tensor =
  let t_added = add t add_t
  in mul t_added mul_t

let scaledDotProductAttention [q_n] [k_n] [v_n] (q : tensor) (k : tensor) (v : tensor) (mask : ?tensor) (scale : f32) : tensor =
  if q.ndim != 4 || k.ndim != 4 || v.ndim != 4 || q.shape[0] != k.shape[0] || q.shape[0] != v.shape[0] || q.shape[1] != k.shape[1] || v.shape[1] != k.shape[1] || q.shape[3] != k.shape[2] || k.shape[3] != v.shape[2] then error "AttentionShapeMismatch"
  else let k_t = transpose k [0, 1, 3, 2]
       let scores = matmul q k_t
       let scores_scaled = divScalar scores (f32.sqrt (f32.i64 q.shape[3]) * scale)
       let scores_m = match mask with
         just m -> add scores_m m
         else -> scores_scaled
       end
       let attn_weights = softmax scores_m (-1)
       in matmul attn_weights v

let multiHeadAttention [n] (t : tensor) (embed_dim : i64) (num_heads : i64) (mask : ?tensor) : tensor =
  let seq_len = t.shape[1]
  let batch_size = t.shape[0]
  let head_dim = embed_dim / num_heads
  let q = copy t
  let k = copy t
  let v = copy t
  let q_resh = reshape q [batch_size, seq_len, num_heads, head_dim]
  let q_trans = transpose q_resh [0, 2, 1, 3]
  let k_resh = reshape k [batch_size, seq_len, num_heads, head_dim]
  let k_trans = transpose k_resh [0, 2, 1, 3]
  let v_resh = reshape v [batch_size, seq_len, num_heads, head_dim]
  let v_trans = transpose v_resh [0, 2, 1, 3]
  let attn = scaledDotProductAttention q_trans k_trans v_trans mask 1.0f32
  let attn_trans = transpose attn [0, 2, 1, 3]
  in reshape attn_trans [batch_size, seq_len, embed_dim]

let embedding [batch] [seq] [embed] [input_n] [weights_n] (input : tensor) (weights : tensor) : tensor =
  if input.ndim != 2 || weights.ndim != 2 then error "EmbeddingShapeMismatch"
  else let vocab = weights.shape[0]
       let emb_dim = weights.shape[1]
       let output_data : [batch*seq*embed]f32 = map (\i ->
         let b = i / (seq * embed)
         let s = (i / embed) % seq
         let e = i % embed
         let idx_f = input.data[b * seq + s]
         let idx = i64.u32 (f32.round idx_f)
         in if 0 <= idx && idx < vocab then
            weights.data[idx * emb_dim + e]
            else 0.0f32
       ) (iota (batch * seq * embed))
       let new_shape = [batch, seq, embed]
       let new_strides = compute_strides new_shape
       in {data = output_data, shape = new_shape, strides = new_strides, ndim = 3}

let positionalEncoding (seq_len : i64) (d_model : i64) (max_len : i64) : tensor =
  let pe = zeros [1, max_len, d_model]
  let data' = loop d = pe.data for pos < seq_len do
    loop d' = d for i < (d_model / 2) do
      let angle = f32.i64 pos / f32.pow 10000.0f32 (f32.i64 (2 * i))
      let d'' = d' with [0 * max_len * d_model + pos * d_model + 2 * i] = f32.sin angle
      in d'' with [0 * max_len * d_model + pos * d_model + 2 * i + 1] = f32.cos angle
  let sh = [1, max_len, d_model]
  let st = compute_strides sh
  in {data = data', shape = sh, strides = st, ndim = 3}

let crossEntropyLoss [batch] [classes] [logits_n] [targets_n] (logits : tensor) (targets : tensor) : f32 =
  if length logits.shape != 2 || length targets.shape != 1 || logits.shape[0] != targets.shape[0] then error "LossShapeMismatch"
  else let loss_terms : [batch]f32 = map (\b ->
    let row_start = b * classes
    let probs : [classes]f32 = slice logits.data row_start classes
    let softmax_probs =  -- implement 1d softmax
      let max_p = reduce f32.max (-f32.inf) probs
      let shifted = map (\x -> f32.exp (x - max_p)) probs
      let sum_s = reduce (+) 0.0f32 shifted
      in map (\x -> x / sum_s) shifted
    let target = i64.u32 (f32.round targets.data[b])
    in if 0 <= target && target < classes then
       -f32.log softmax_probs[target]
       else 0.0f32
  ) (iota batch)
  in reduce (+) 0.0f32 loss_terms / f32.i64 batch

let adamUpdate [n] (params : tensor) (grads : tensor) (m : tensor) (v : tensor) (t : f32) (lr : f32) (beta1 : f32) (beta2 : f32) (eps : f32) : tensor =
  let beta1_t = 1.0f32 - f32.pow beta1 t
  let beta2_t = 1.0f32 - f32.pow beta2 t
  let m_new = addScalar (mulScalar m beta1) ((1.0f32 - beta1) * f32.i64 1)  -- simplistic, map
  let m_new = add m_new (mulScalar grads (1.0f32 - beta1))
  let v_new = addScalar (mulScalar v beta2) ((1.0f32 - beta2) * f32.i64 1)
  let grad_sq = mul grads grads
  let v_new = add v_new (mulScalar grad_sq (1.0f32 - beta2))
  let m_hat = divScalar m_new beta1_t
  let v_hat = addScalar (divScalar v_new beta2_t) eps
  let v_hat_sqrt = sqrt v_hat
  let update = mulScalar (div m_hat v_hat_sqrt) lr
  in sub params update
